{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the contribution of model-based and model-free values to the first-stage net Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1.0 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_stickiness",
      "title": "Stage 1 Choice Stickiness",
      "description": "Adds a bonus to the first-stage logits for the action chosen on the previous trial.",
      "params": [
        {
          "name": "stickiness_1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_action_1 != -1:\n            logits_1[last_action_1] += stickiness_1",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_stickiness",
      "title": "Stage 2 Choice Stickiness",
      "description": "Adds a bonus to the second-stage logits for the action chosen on the previous visit to the current state.",
      "params": [
        {
          "name": "stickiness_2",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if last_action_2[state_idx] != -1:\n            logits_2[last_action_2[state_idx]] += stickiness_2",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the first-stage model-free Q-value for the chosen action using the second-stage reward prediction error.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Decays the Q-values of unchosen actions and unvisited states towards zero.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_1 = 1 - action_1[trial]\n        q_stage1_mf[unchosen_1] *= (1.0 - decay)\n        \n        unchosen_2 = 1 - action_2[trial]\n        q_stage2_mf[state_idx, unchosen_2] *= (1.0 - decay)\n        \n        unvisited_state = 1 - state_idx\n        q_stage2_mf[unvisited_state, :] *= (1.0 - decay)",
      "expressible_in_slots": true
    }
  ]
}
